window.addEventListener('keydown',e=>{if(editingText(e)||drag||document.querySelector('dialog[open]'))return;const key=e.key.toLowerCase(),cmd=e.ctrlKey||e.metaKey;if(!cmd&&!e.altKey&&!e.isComposing&&!e.repeat&&!document.querySelector('dialog[open]')&&toolShortcuts[key]){e.preventDefault();setTool(toolShortcuts[key]);canvas.focus({preventScroll:true});return;}if(!cmd&&!e.altKey&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&selected.length){e.preventDefault();finish();selected=selected.filter(i=>i.isInserted());const amount=nudgeAmount(e.shiftKey),step=amount*units[$('units').value],delta={ArrowLeft:[-step,0],ArrowRight:[step,0],ArrowUp:[0,-step],ArrowDown:[0,step]}[e.key];if(tool==='nodes'&&selectedNodes.length)selectedNodes.forEach(s=>s.point=s.point.add(pathVector(s.path,new paper.Point(delta))));else selected.forEach(i=>i.translate(delta));commit();say(`Moved ${amount} ${$('units').value}`);}else if(!cmd&&!e.altKey&&(key==='-'||key==='='||key==='+')){e.preventDefault();zoom(key==='-'?.8:1.25,cursorViewPoint());}else if(cmd&&key==='a'){e.preventDefault();finish();if(tool==='nodes'){if(!selected.length)selected=[...art.children];selectedNodes=selected.flatMap(editablePaths).flatMap(p=>p.segments);}else{setTool('select');selected=[...art.children];}refresh();}else if(cmd&&key==='g'&&!e.altKey){e.preventDefault();if(!e.repeat&&!e.isComposing)$(e.shiftKey?'ungroup-objects':'group-objects').click();}else if(cmd&&key==='d'){e.preventDefault();$('duplicate').click();}else if(cmd&&key==='s'){e.preventDefault();$('save').click();}else if(cmd&&(key==='z'||key==='y')){e.preventDefault();(key==='y'||e.shiftKey?$('redo'):$('undo')).click();}else if(e.key==='Escape'||e.key==='Enter')finish();else if(e.key==='Delete'||e.key==='Backspace'){$('delete').click();e.preventDefault();}});
