function applyDropper(sample){const {width,height,data}=sample.pixels,scale=width/paper.view.viewSize.width,center=paper.view.projectToView(sample.start).multiply(scale),radius=sample.radius*paper.view.zoom*scale;const pageStart=paper.view.projectToView(new paper.Point(0,0)).multiply(scale),pageEnd=paper.view.projectToView(new paper.Point(pageSize.width,pageSize.height)).multiply(scale);const pointSample=radius<2*scale,r=pointSample?0:radius,minX=Math.max(0,Math.floor(center.x-r),Math.ceil(pageStart.x-.5)),maxX=Math.min(width-1,Math.floor(center.x+r),Math.ceil(pageEnd.x-.5)-1),minY=Math.max(0,Math.floor(center.y-r),Math.ceil(pageStart.y-.5)),maxY=Math.min(height-1,Math.floor(center.y+r),Math.ceil(pageEnd.y-.5)-1);let red=0,green=0,blue=0,count=0;for(let y=minY;y<=maxY;y++)for(let x=minX;x<=maxX;x++){if(!pointSample&&(x+.5-center.x)**2+(y+.5-center.y)**2>r*r)continue;const i=(y*width+x)*4,alpha=data[i+3]/255;red+=data[i]*alpha+255*(1-alpha);green+=data[i+1]*alpha+255*(1-alpha);blue+=data[i+2]*alpha+255*(1-alpha);count++;}if(!count)return say('Sample inside the artboard.');const hex='#'+[red,green,blue].map(v=>Math.round(v/count).toString(16).padStart(2,'0')).join('');$(sample.target).setColor(hex,1);if(sample.target==='fill')$('no-fill').checked=false;const color=pickerColor(sample.target);selected.filter(i=>!imageParts(i)).forEach(i=>i[`${sample.target}Color`]=color.clone());commit();say(`Sampled ${hex} → ${sample.target==='fill'?'fill':'outline'}`);}

