async function insertImages(files){finish();try{const added=[];for(const file of files){if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type))throw Error('Choose a PNG, JPEG, WebP, or GIF image.');if(file.size>15e6)throw Error('Please use images smaller than 15 MB.');const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read image.'));reader.readAsDataURL(file);});const image=new Image();image.src=source;await image.decode();const raster=new paper.Raster({image,insert:false});const scale=Math.min(1,pageSize.width*.7/raster.width,pageSize.height*.7/raster.height);raster.scale(scale);const mask=new paper.Path.Rectangle({rectangle:raster.bounds,insert:false});mask.clipMask=true;const group=new paper.Group({children:[mask,raster],insert:false});group.data.image=true;group.applyMatrix=false;group.position=new paper.Point(pageSize.width/2+added.length*20,pageSize.height/2+added.length*20);art.addChild(group);added.push(group);}selected=added;setTool('select');commit();say('Image inserted. Crop controls are above the canvas.');}catch(error){commit();say(error.message||'Could not decode image.');}}
