function applyPageDimension(axis){const field=$(`page-${axis}`),value=field.valueAsNumber*units[$('units').value];if(!Number.isFinite(value)||value<=0||value>100000)return say('Enter a positive artboard dimension up to 100,000 pixels.');finish();pageSize={...pageSize,[axis]:value};delete field.dataset.pending;commit();say('Artboard dimension applied');}
for(const axis of ['width','height']){const field=$(`page-${axis}`);field.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();if(field.dataset.pending)applyPageDimension(axis);}});field.addEventListener('blur',()=>{if(field.dataset.pending)applyPageDimension(axis);});}
for(const id of ['position-x','position-y'])$(id).addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('apply-position').click();}});

const dimensionFields=['position-x','position-y','dimension-width','dimension-height','page-width','page-height','handle-width','handle-height'];
for(const input of new Set([...dimensionFields.map($),...document.querySelectorAll('input[type=number]')])){const id=input.id;input.type='text';input.inputMode='decimal';Object.defineProperty(input,'valueAsNumber',{get(){return this.value.trim()?Number(this.value):NaN;}});input.addEventListener('input',()=>{if(!dimensionFields.includes(id))return;const pending=input.value!==input.dataset.actual;if(pending)input.dataset.pending='true';else delete input.dataset.pending;input.classList.toggle('pending',pending);});input.enterKeyHint='done';input.addEventListener('blur',()=>{preserveDimensionViewUntil=Date.now()+800;});input.addEventListener('focus',()=>{preserveDimensionViewUntil=Date.now()+800;setTimeout(()=>{if(document.activeElement===input)input.select();},0);});input.addEventListener('pointerup',e=>{if(e.pointerType==='touch'||e.detail>1)setTimeout(()=>input.select(),0);});input.addEventListener('dblclick',()=>input.select());}
const applyPosition=$('apply-position').onclick;$('apply-position').onclick=()=>{applyPosition();updateDimensions();};
var dimensionLabels=document.createElement('div');dimensionLabels.id='dimension-labels';dimensionLabels.innerHTML='<button type="button" id="selection-width-label" aria-label="Edit selection width"></button><button type="button" id="selection-height-label" aria-label="Edit selection height"></button>';$('stage').append(dimensionLabels);
function syncDimensionLabels(){if(!dimensionLabels)return;const bounds=selectionBounds();dimensionLabels.hidden=!bounds||tool!=='select'||!!drag;if(dimensionLabels.hidden)return;const stage=$('stage'),clamp=(v,max)=>Math.max(4,Math.min(v,max));for(const axis of ['width','height']){const button=$(`selection-${axis}-label`),p=paper.view.projectToView(axis==='width'?bounds.bottomCenter:bounds.rightCenter);button.textContent=`${formatLength(bounds[axis])} ${$('units').value}`;button.style.left=`${clamp(p.x+(axis==='width'?-button.offsetWidth/2:12),stage.clientWidth-button.offsetWidth-4)}px`;button.style.top=`${clamp(p.y+(axis==='width'?12:-button.offsetHeight/2),stage.clientHeight-button.offsetHeight-4)}px`;}}
for(const axis of ['width','height'])$(`selection-${axis}-label`).onclick=()=>{const bounds=selectionBounds();showHandleSize({name:'se',axis,anchor:bounds.topLeft.clone()});const input=$(`handle-${axis}`);input.dataset.actual=input.value;delete input.dataset.pending;input.classList.remove('pending');};
const unitSelect=$('units');unitSelect.hidden=true;
const unitButton=document.createElement('button');unitButton.id='unit-button';unitButton.type='button';unitButton.setAttribute('aria-label','Page units');unitButton.setAttribute('aria-expanded','false');unitButton.textContent=unitSelect.value+' ▾';unitSelect.parentElement.append(unitButton);
const unitMenu=document.createElement('div');unitMenu.id='unit-menu';unitMenu.hidden=true;unitMenu.setAttribute('role','group');unitMenu.setAttribute('aria-label','Choose units');unitSelect.parentElement.append(unitMenu);unitButton.setAttribute('aria-controls','unit-menu');
for(const unit of Object.keys(units)){const button=document.createElement('button');button.type='button';button.textContent=unit;button.onclick=()=>{unitSelect.value=unit;unitSelect.dispatchEvent(new Event('change',{bubbles:true}));unitMenu.hidden=true;unitButton.setAttribute('aria-expanded','false');};unitMenu.append(button);}
unitButton.onclick=()=>{unitMenu.hidden=!unitMenu.hidden;unitButton.setAttribute('aria-expanded',String(!unitMenu.hidden));};unitSelect.addEventListener('change',()=>unitButton.textContent=unitSelect.value+' ▾');document.addEventListener('pointerdown',e=>{if(!unitSelect.parentElement.contains(e.target)){unitMenu.hidden=true;unitButton.setAttribute('aria-expanded','false');}});syncDimensionLabels();

$('text-bold').onchange=async()=>{const item=selected.length===1&&selected[0] instanceof paper.PointText?selected[0]:null;if(!item)return;try{await fontReady;item.fontWeight=$('text-bold').checked?'bold':'normal';commit();say('Text weight updated');}catch(error){say(error.message);}};

$('return-to-page').onclick=()=>{fit();canvas.focus({preventScroll:true});say('Page centered');};
document.addEventListener('pointerdown',e=>{for(const menu of [$('page-settings'),$('image-crop').querySelector('details')])if(menu.open&&!menu.contains(e.target))menu.open=false;});

const toolShortcuts={s:'select',n:'nodes',t:'text',p:'pen',r:'rectangle',e:'ellipse',d:'dropper',b:'bucket',l:'blob',c:'crop',h:'pan'};
const shortcutHint=document.createElement('div');shortcutHint.id='shortcut-hint';shortcutHint.setAttribute('role','tooltip');shortcutHint.hidden=true;document.body.append(shortcutHint);
let shortcutHold,shortcutDismiss,shortcutStart,shortcutShown=false;
function hideShortcutHint(){clearTimeout(shortcutHold);clearTimeout(shortcutDismiss);shortcutHint.hidden=true;}
for(const button of document.querySelectorAll('main>aside:first-child button')){const key=button.dataset.tool?Object.keys(toolShortcuts).find(key=>toolShortcuts[key]===button.dataset.tool):button.id==='undo'?'Ctrl/Cmd+Z':button.id==='redo'?'Ctrl/Cmd+Shift+Z':null;if(!key)continue;const label=button.querySelector('span')?.textContent||button.textContent.trim();button.title=`${label} (${key.length===1?key.toUpperCase():key})`;button.setAttribute('aria-label',button.title);button.setAttribute('aria-keyshortcuts',key.length===1?key:'Control+'+(button.id==='undo'?'z':'Shift+z'));button.addEventListener('pointerdown',e=>{hideShortcutHint();shortcutShown=false;if(e.pointerType!=='touch'&&e.pointerType!=='pen')return;shortcutStart={x:e.clientX,y:e.clientY};shortcutHold=setTimeout(()=>{shortcutShown=true;shortcutHint.textContent=button.title;shortcutHint.hidden=false;const r=button.getBoundingClientRect();shortcutHint.style.left=`${Math.min(r.right+8,innerWidth-shortcutHint.offsetWidth-8)}px`;shortcutHint.style.top=`${Math.max(8,Math.min(r.top,innerHeight-shortcutHint.offsetHeight-8))}px`;button.setAttribute('aria-describedby','shortcut-hint');},500);});button.addEventListener('pointermove',e=>{if(shortcutStart&&Math.hypot(e.clientX-shortcutStart.x,e.clientY-shortcutStart.y)>10)hideShortcutHint();});button.addEventListener('pointerup',()=>{clearTimeout(shortcutHold);shortcutStart=null;shortcutDismiss=setTimeout(hideShortcutHint,2500);});button.addEventListener('pointercancel',hideShortcutHint);button.addEventListener('contextmenu',e=>e.preventDefault());button.addEventListener('click',e=>{if(shortcutShown){e.preventDefault();e.stopImmediatePropagation();shortcutShown=false;}},true);}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('main>aside:first-child'))hideShortcutHint();});
const mobileTools=document.createElement('button');mobileTools.id='mobile-tools';mobileTools.className='mobile-menu-button';mobileTools.textContent='Tools';mobileTools.setAttribute('aria-expanded','false');mobileTools.setAttribute('aria-controls','drawing-tools');
const mobileProperties=document.createElement('button');mobileProperties.id='mobile-properties';mobileProperties.className='mobile-menu-button';mobileProperties.textContent='Properties';mobileProperties.setAttribute('aria-expanded','false');mobileProperties.setAttribute('aria-controls','object-properties');document.querySelector('.top-controls').prepend(mobileTools,mobileProperties);
const toolsDrawer=document.querySelector('main>aside:first-child'),propertiesDrawer=document.querySelector('.properties');toolsDrawer.id='drawing-tools';propertiesDrawer.id='object-properties';
const drawerShade=document.createElement('button');drawerShade.id='drawer-shade';drawerShade.hidden=true;drawerShade.setAttribute('aria-label','Close tool menu');document.body.append(drawerShade);
function closeMobileMenus(){document.body.classList.remove('tools-open','properties-open');drawerShade.hidden=true;mobileTools.setAttribute('aria-expanded','false');mobileProperties.setAttribute('aria-expanded','false');}
function toggleMobileMenu(name){const wasOpen=document.body.classList.contains(`${name}-open`);closeMobileMenus();if(!wasOpen){document.body.classList.add(`${name}-open`);drawerShade.hidden=false;(name==='tools'?mobileTools:mobileProperties).setAttribute('aria-expanded','true');}}
mobileTools.onclick=()=>toggleMobileMenu('tools');mobileProperties.onclick=()=>toggleMobileMenu('properties');drawerShade.onclick=closeMobileMenus;
for(const drawer of [toolsDrawer,propertiesDrawer]){const close=document.createElement('button');close.className='mobile-menu-close';close.textContent='Close ×';close.onclick=closeMobileMenus;drawer.prepend(close);}
toolsDrawer.addEventListener('click',e=>{if(e.target.closest('[data-tool],#undo,#redo')&&matchMedia('(max-width:700px), (max-height:500px) and (orientation:landscape)').matches)closeMobileMenus();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMobileMenus();});matchMedia('(max-width:700px), (max-height:500px) and (orientation:landscape)').addEventListener('change',closeMobileMenus);
const mobileToolbarShell=document.createElement('div');mobileToolbarShell.className='mobile-toolbar-shell';const toolbarContext=document.querySelector('.context');toolbarContext.before(mobileToolbarShell);mobileToolbarShell.append(mobileTools,mobileProperties,toolbarContext);

const mobileFile=document.createElement('button');mobileFile.id='mobile-file';mobileFile.className='mobile-file-button';mobileFile.textContent='File ▾';mobileFile.setAttribute('aria-expanded','false');document.querySelector('header nav').id='file-actions';mobileFile.setAttribute('aria-controls','file-actions');mobileToolbarShell.prepend(mobileFile);
function closeMobileFile(){document.body.classList.remove('files-open');mobileFile.setAttribute('aria-expanded','false');}
mobileFile.onclick=()=>{const open=document.body.classList.toggle('files-open');mobileFile.setAttribute('aria-expanded',String(open));closeMobileMenus();};document.querySelector('header nav').addEventListener('click',e=>{if(e.target.closest('button'))closeMobileFile();});document.addEventListener('pointerdown',e=>{if(!e.target.closest('header nav,#mobile-file'))closeMobileFile();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMobileFile();});matchMedia('(max-height:500px) and (orientation:landscape)').addEventListener('change',closeMobileFile);

// Fixed popovers escape the scrolling toolbar without clipping or changing its
// size. Re-anchor them as controls scroll, resize, or open a native details menu.
function positionToolbarMenus(){
  const crop=document.querySelector('#image-crop details');
  for(const [menu,anchor,open] of [[$('unit-menu'),$('unit-button'),!$('unit-menu').hidden],[$('snap-menu'),$('snap-button'),!$('snap-menu').hidden],[document.querySelector('#page-settings .toolbar-popover'),document.querySelector('#page-settings summary'),$('page-settings').open],[document.querySelector('.crop-popover'),crop.querySelector('summary'),crop.open]]){
    if(!open)continue;
    const r=anchor.getBoundingClientRect();menu.style.setProperty('--menu-left',Math.max(8,Math.min(r.left,innerWidth-menu.offsetWidth-8))+'px');menu.style.setProperty('--menu-top',Math.max(4,Math.min(r.bottom+6,innerHeight-menu.offsetHeight-8))+'px');
  }
}
document.addEventListener('click',positionToolbarMenus);window.addEventListener('resize',positionToolbarMenus);
document.querySelector('.context').addEventListener('scroll',positionToolbarMenus);
for(const menu of [$('page-settings'),document.querySelector('#image-crop details')])menu.addEventListener('toggle',positionToolbarMenus);
